import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const packageRoot = resolve(here, "..");
const outFile = resolve(packageRoot, "types", "index.d.ts");

const content = `// Auto-generated by scripts/generate-types.mjs
// Do not edit manually.

declare module "weiv:observable" {
  export type Listener = () => void;

  export function observable<T extends object>(value: T): T;
  export function subscribe<T extends object>(value: T, listener: Listener): () => void;
  export function snapshot<T>(value: T): T;
  export function isObservable(value: unknown): boolean;
  export function observableBrandSymbol(): symbol;
}

declare module "weiv:router" {
  export type RouteParams = Record<string, string>;
  export type QueryParams = Record<string, string>;

  export type RouteState = {
    path: string;
    params: RouteParams;
    query: QueryParams;
    matched: string | null;
  };

  export type NavigationContext = {
    from: RouteState;
    to: RouteState;
  };

  export type GuardResult = void | boolean | string;
  export type NavigationGuard = (ctx: NavigationContext) => GuardResult | Promise<GuardResult>;
  export type LeaveGuard = (ctx: NavigationContext) => GuardResult | Promise<GuardResult>;

  export type RouteDefinition = {
    path: string;
    component: () => any | Promise<any>;
    props?: (route: RouteState) => Record<string, any>;
    children?: RouteDefinition[];
    beforeEnter?: NavigationGuard;
    beforeLeave?: LeaveGuard;
  };

  export type RouterOptions = {
    mode?: "history" | "hash";
    base?: string;
    routes: RouteDefinition[];
    target: Element;
    scrollBehavior?: (
      ctx: NavigationContext,
      savedPosition: { x: number; y: number } | null,
    ) => { x?: number; y?: number; el?: string } | void;
  };

  export type Router = {
    route: RouteState;
    ready: Promise<void>;
    push(path: string): Promise<void>;
    replace(path: string): Promise<void>;
    back(): void;
    forward(): void;
    beforeEach(guard: NavigationGuard): () => void;
    afterEach(guard: (ctx: NavigationContext) => void | Promise<void>): () => void;
    destroy(): void;
  };

  export function createRouter(options: RouterOptions): Router;
}

export {};
`;

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, content, "utf8");
console.log(`Generated ${outFile}`);
